import React, { useState } from 'react';
import axios from 'axios';

const FormulaForm = ({ appointmentId, token }) => {
  // State for the core appointment detail fields
  const [style, setStyle] = useState('');
  const [materials, setMaterials] = useState('');

  // State for our structured layer-by-layer recipe
  const [baseCoat, setBaseCoat] = useState('');
  const [colorLayers, setColorLayers] = useState(['']); // Array for multiple gel layers
  const [topCoat, setTopCoat] = useState('');

  // Status and error messaging
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  // Setup Axios secure authorization headers using your JWT token
  const api = axios.create({
    baseURL: 'http://127.0.0.1:8000/api/',
    headers: { Authorization: `Bearer ${token}` }
  });

  // Handle adding/removing dynamic color polish layers (e.g., 1 coat Bubble Bath + 1 coat Funny Bunny)
  const handleAddLayer = () => setColorLayers([...colorLayers, '']);
  const handleLayerChange = (index, value) => {
    const updatedLayers = [...colorLayers];
    updatedLayers[index] = value;
    setColorLayers(updatedLayers);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    // Package the formulation recipe into the exact JSON format our Django backend expects
    const payload = {
      detail: {
        style: style,
        materials: materials.split(',').map(item => item.trim()), // Turn comma-separated string into an array
        formula_recipe: {
          base: baseCoat,
          layers: colorLayers.filter(layer => layer.trim() !== ''),
          top: topCoat
        }
      }
    };

    try {
      // Submits data directly to our live Django appointment details endpoint
      await api.patch(`appointments/${appointmentId}/`, payload);
      setMessage('✅ Formula successfully saved to client history!');
    } catch (err) {
      console.error(err);
      setMessage('❌ Failed to save formula. Please check backend connection.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <h2 style={styles.heading}>💅 Log Set Formula</h2>
      <p style={styles.subheading}>Build the client's layer formulation stack</p>

      {message && <div style={styles.alert}>{message}</div>}

      <form onSubmit={handleSubmit} style={styles.form}>
        {/* Style & Aesthetic Goal */}
        <div style={styles.formGroup}>
          <label style={styles.label}>Set Style Description</label>
          <input 
            type="text" 
            placeholder="e.g., Almond French Tip w/ Pearl Chrome" 
            value={style} 
            onChange={(e) => setStyle(e.target.value)}
            style={styles.input}
            required
          />
        </div>

        {/* Structure / Base Layer */}
        <div style={styles.formGroup}>
          <label style={styles.label}>1. Base Layer / Structure Gel</label>
          <input 
            type="text" 
            placeholder="e.g., Après Gel-X / Jimmy Gel / BIAB" 
            value={baseCoat} 
            onChange={(e) => setBaseCoat(e.target.value)}
            style={styles.input}
          />
        </div>

        {/* Dynamic Color Polish Stack */}
        <div style={styles.formGroup}>
          <label style={styles.label}>2. Polish Layers (In order of application)</label>
          {colorLayers.map((layer, index) => (
            <div key={index} style={{ display: 'flex', marginBottom: '8px' }}>
              <input 
                type="text" 
                placeholder={`Layer ${index + 1} (e.g., OPI Funny Bunny)`} 
                value={layer} 
                onChange={(e) => handleLayerChange(index, e.target.value)}
                style={styles.input}
              />
            </div>
          ))}
          <button type="button" onClick={handleAddLayer} style={styles.addButton}>
            + Add Another Color Layer
          </button>
        </div>

        {/* Top Finish Layer */}
        <div style={styles.formGroup}>
          <label style={styles.label}>3. Top Finish</label>
          <input 
            type="text" 
            placeholder="e.g., Valentino Super Glossy / Matte Top" 
            value={topCoat} 
            onChange={(e) => setTopCoat(e.target.value)}
            style={styles.input}
          />
        </div>

        {/* Hard Accessories */}
        <div style={styles.formGroup}>
          <label style={styles.label}>Accessories & Materials (Comma separated)</label>
          <input 
            type="text" 
            placeholder="e.g., Swarovski crystals, silver foil, 3D charms" 
            value={materials} 
            onChange={(e) => setMaterials(e.target.value)}
            style={styles.input}
          />
        </div>

        <button type="submit" disabled={loading} style={styles.submitButton}>
          {loading ? 'Saving to Database...' : 'Save Formula to Appointment'}
        </button>
      </form>
    </div>
  );
};

// Quick scannable inline styles for clean UX
const styles = {
  container: { maxWidth: '500px', margin: '30px auto', padding: '25px', backgroundColor: '#fff', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.08)', fontFamily: 'system-ui, sans-serif' },
  heading: { margin: '0 0 5px 0', fontSize: '24px', color: '#111' },
  subheading: { margin: '0 0 20px 0', fontSize: '14px', color: '#666' },
  formGroup: { marginBottom: '18px' },
  label: { display: 'block', marginBottom: '6px', fontSize: '14px', fontWeight: '600', color: '#444' },
  input: { width: '100%', padding: '10px 12px', boxSizing: 'border-box', border: '1px solid #ccc', borderRadius: '6px', fontSize: '14px' },
  addButton: { background: 'none', border: 'none', color: '#0070f3', fontSize: '13px', fontWeight: '500', cursor: 'pointer', padding: 0 },
  submitButton: { width: '100%', padding: '12px', backgroundColor: '#111', color: '#fff', border: 'none', borderRadius: '6px', fontSize: '15px', fontWeight: '600', cursor: 'pointer', marginTop: '10px' },
  alert: { padding: '12px', backgroundColor: '#f0fdf4', color: '#166534', borderRadius: '6px', fontSize: '14px', marginBottom: '15px', border: '1px solid #bbf7d0' }
};

export default FormulaForm;
